import sys

def solve():
    s = sys.stdin.readline().strip()
    n = len(s)
    total = 0.0

    for k in range(n):
        first_char = s[k]
        found = False
        for second_pos in range(1, n):
            second_char = s[(k + second_pos) % n]
            unique = True
            for k2 in range(n):
                if k2 == k:
                    continue
                if s[k2] == first_char and s[(k2 + second_pos) % n] == second_char:
                    unique = False
                    break
            if unique:
                found = True
                break
        if found:
            total += 1.0

    probability = total / n
    print(probability)

solve()
